7.1 Packages
The R packages required for preparing the model dataset and fitting the full model.
Code
library(tidyverse)
library(brms)
library(posterior)
library(bayesplot)
library(loo)

options(mc.cores = parallel::detectCores())

first_existing &lt;- function(paths) {
  existing &lt;- paths[file.exists(paths)]
  if (length(existing) == 0) {
    return(NA_character_)
  }
  existing[1]
}
